import os
import json
import re
import string
from collections import Counter
def task_func(json_dir_path, word_count):
    all_text = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as json_file:
                try:
                    data = json.load(json_file)
                    if 'text' in data:
                        all_text.append(data['text'])
                except json.JSONDecodeError:
                    continue
    combined_text = ' '.join(all_text)
    combined_text = re.sub('[^\sa-zA-Z0-9]', '', combined_text).lower().strip()
    combined_text = combined_text.translate({ord(c): None for c in string.punctuation})
    word_counts = Counter(combined_text.split())
    return word_counts.most_common(word_count)

